"""Audit MP4 and JSON generated by offline_clip_export.export_clip (schema v1)."""
import hashlib
import json
import math
from pathlib import Path
import re
import subprocess

HEX = re.compile(r'[0-9a-f]{64}\Z')

def sha256(path):
    h = hashlib.sha256()
    with open(path, 'rb') as f:
        for block in iter(lambda: f.read(1024 * 1024), b''):
            h.update(block)
    return h.hexdigest()

def unique(pairs):
    result = {}
    for k, v in pairs:
        if k in result:
            raise ValueError('duplicate JSON key')
        result[k] = v
    return result

def audit_export_pair(clip, source=None):
    clip = Path(clip)
    sidecar = Path(str(clip) + '.json')
    if any(p.is_symlink() or not p.is_file() for p in (clip, sidecar)):
        raise ValueError('missing or unsafe artifact')
    if sidecar.stat().st_size > 65536:
        raise ValueError('oversized sidecar')
    data = json.loads(sidecar.read_text(encoding='utf-8'), object_pairs_hook=unique,
                      parse_constant=lambda x: (_ for _ in ()).throw(ValueError(x)))
    if not isinstance(data, dict) or type(data.get('schema_version')) is not int or data['schema_version'] != 1:
        raise ValueError('unsupported schema')
    if data.get('strategic_verdict_allowed') is not False or data.get('review_status') not in ('confirmed', 'insufficient_data'):
        raise ValueError('untrusted review state')
    label = 'INSUFFICIENT_DATA' if data['review_status'] == 'insufficient_data' else 'CONDITIONAL MODEL ONLY'
    if data.get('annotation') != label:
        raise ValueError('annotation mismatch')
    for key in ('clip_sha256', 'source_sha256'):
        if not isinstance(data.get(key), str) or not HEX.fullmatch(data[key]):
            raise ValueError('invalid digest')
    if sha256(clip) != data['clip_sha256']:
        raise ValueError('clip digest mismatch')
    if source is not None:
        source = Path(source)
        if source.is_symlink() or not source.is_file() or sha256(source) != data['source_sha256']:
            raise ValueError('source digest mismatch')
    start, end, actual = (data.get(k) for k in ('start_seconds', 'end_seconds', 'actual_clip_duration_seconds'))
    if any(type(x) not in (int, float) or not math.isfinite(x) for x in (start, end, actual)) or not 0 <= start < end or actual <= 0:
        raise ValueError('invalid timestamps')
    if abs(actual - (end - start)) > 0.25:
        raise ValueError('declared duration mismatch')
    result = subprocess.run(['ffprobe', '-v', 'error', '-show_entries', 'format=duration:stream=codec_type',
                             '-of', 'json', str(clip)], check=True, capture_output=True, text=True, timeout=30)
    info = json.loads(result.stdout)
    if not any(s.get('codec_type') == 'video' for s in info.get('streams', [])):
        raise ValueError('no video stream')
    duration = float(info['format']['duration'])
    if not math.isfinite(duration) or duration <= 0 or abs(duration - actual) > 0.05:
        raise ValueError('FFprobe duration mismatch')
    return {'artifact_integrity_verified': True, 'source_checked': source is not None,
            'clip_sha256': data['clip_sha256'], 'strategic_analysis_verified': False,
            'duration_seconds': duration}
